function demoMain(idx,label){
  var ch=[["#dev",14],["#random",32],["#alerts",5]];var c=ch[idx%ch.length];
  return "["+label+"] channel "+c[0]+": "+c[1]+" messages today, "+Math.max(1,c[1]>>3)+" threads resolved";
}

